mapper.select:
SELECT id, note_id, user_id, content_uuid, is_content_empty, image_url, `level`, reply_total, like_total, parent_id, reply_comment_id, reply_user_id, is_top, create_time, update_time, child_comment_total, first_reply_comment_id, heat FROM comment WHERE note_id = #{noteId} AND `level` = 1 AND parent_id = #{noteId}
AND (heat < #{cursorHeat} OR (heat = #{cursorHeat} AND id > #{cursor}))
ORDER BY heat DESC, id ASC LIMIT #{limit}

SELECT id, note_id, user_id, content_uuid, is_content_empty, image_url,
       `level`, reply_total, like_total, parent_id, reply_comment_id,
       reply_user_id, is_top, create_time, update_time, child_comment_total,
       first_reply_comment_id, heat
FROM comment
WHERE note_id = #{noteId}
  AND `level` = 2
  AND parent_id = #{parentId}

  AND id > #{cursor}

ORDER BY id ASC
LIMIT #{limit}
